# Reviewed script: the KANO VERTICAL SLICE GREYBOX. Everything here is a PLACEHOLDER VOLUME, not architecture.
# Inputs (args): geometry = docs/kano/kano_slice_geometry.json (the game's own RouteModel road geometry, terrain heights and every prefab instance PropScatter places),
#                inventory = docs/kano/kano_asset_inventory.json (the planned prefab envelopes). Both are generated by tests/NetCore.Tests/KanoSliceTests.cs, so this scene is what the game
#                would place, at the game's scale and orientation. Unity (x east, y up, z north, prefab front +Z, yaw = bearing) -> Blender (X east, Y north, Z up, asset front -Y).
# Colours code the CATEGORY of each volume (see the legend in the result); they say nothing about real colours or materials. No reference-driven detail exists yet: plots are solid envelopes
# with a flat front apron, trees are balls on sticks, the mosque is a block with a tall thin tower marking its planned height. The only judgement a greybox invites is rhythm, scale and layout.
import json, math
from pathlib import Path

G = json.loads(Path(args["geometry"]).read_text(encoding="utf-8"))
INV = {p["id"]: p for p in json.loads(Path(args["inventory"]).read_text(encoding="utf-8"))["props"]}
aro_scene.clear(bpy)
GROUND_DROP = 0.12          # the ground mesh is a 20 m grid of the game's heights: sink it a little so the road ribbon never z-fights with it

COLOURS = {   # category coding for review, NOT materials
    "ground": (0.42, 0.34, 0.24), "asphalt_good": (0.055, 0.055, 0.06), "asphalt_worn": (0.11, 0.105, 0.10), "asphalt_damaged": (0.20, 0.17, 0.15),
    "shoulder": (0.30, 0.29, 0.27), "verge": (0.48, 0.38, 0.25), "median": (0.62, 0.62, 0.60), "apron": (0.55, 0.55, 0.53),
    "plot_traditional": (0.74, 0.46, 0.26), "plot_modern": (0.55, 0.66, 0.80), "plot_commercial": (0.86, 0.72, 0.22), "tall_modern": (0.62, 0.52, 0.78),
    "religious": (0.20, 0.62, 0.36), "fuel": (0.82, 0.26, 0.20), "street_props": (0.92, 0.56, 0.10), "poles_lights_signs": (0.10, 0.10, 0.11),
    "billboard": (0.88, 0.40, 0.62), "tree": (0.13, 0.38, 0.14), "ground_cover": (0.40, 0.55, 0.22), "vehicles": (0.30, 0.52, 0.85),
}
MATS = {}
def mat(key):
    if key not in MATS:
        m = bpy.data.materials.new("GB_" + key); m.use_nodes = True; c = COLOURS[key] + (1.0,)
        b = m.node_tree.nodes.get("Principled BSDF")
        if b: b.inputs["Base Color"].default_value = c; b.inputs["Roughness"].default_value = 0.95
        m.diffuse_color = c; MATS[key] = m
    return MATS[key]

B = {}   # material key -> [verts, faces]
def buf(key): return B.setdefault(key, [[], []])
def quad(key, a, b, c, d): v, f = buf(key); i = len(v); v.extend([a, b, c, d]); f.append((i, i + 1, i + 2, i + 3))
def box_world(key, corners):          # corners: 8 world points, bottom (0..3 counter-clockwise) then top (4..7)
    for q in ((0, 3, 2, 1), (4, 5, 6, 7), (0, 1, 5, 4), (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7)): quad(key, *[corners[i] for i in q])

class Inst:
    """Local frame of one prefab instance: origin at the footprint centre on the ground, front -Y, width X, height Z; scale s; rotated so the front points along the bearing `yaw`."""
    def __init__(self, x, y, z, yaw, s): self.x, self.y, self.z, self.s = x, y - GROUND_DROP * 0.5, z, s; self.phi = math.radians(180.0 - yaw); self.c, self.sn = math.cos(self.phi), math.sin(self.phi)
    def w(self, lx, ly, lz): lx, ly, lz = lx * self.s, ly * self.s, lz * self.s; return (self.x + lx * self.c - ly * self.sn, self.z + lx * self.sn + ly * self.c, self.y + lz)
    def box(self, key, cx, cy, z0, w, d, h):
        hx, hy = w / 2, d / 2
        pts = [(cx - hx, cy - hy), (cx + hx, cy - hy), (cx + hx, cy + hy), (cx - hx, cy + hy)]
        box_world(key, [self.w(px, py, z0) for px, py in pts] + [self.w(px, py, z0 + h) for px, py in pts])
    def prism(self, key, cx, cy, z0, dia, h, n=8):     # a round post / ball approximated by an n-gon prism
        r = dia / 2; ring = [(cx + r * math.cos(2 * math.pi * k / n), cy + r * math.sin(2 * math.pi * k / n)) for k in range(n)]
        bot = [self.w(px, py, z0) for px, py in ring]; top = [self.w(px, py, z0 + h) for px, py in ring]
        for k in range(n): quad(key, bot[k], bot[(k + 1) % n], top[(k + 1) % n], top[k])
        v, f = buf(key); i = len(v); v.extend(top); f.append(tuple(range(i, i + n)))
        i = len(v); v.extend(reversed(bot)); f.append(tuple(range(i, i + n)))
    def ball(self, key, cx, cy, cz, rx, rz, rings=4, segs=8):   # squashed sphere
        pts = []
        for a in range(rings + 1):
            t = math.pi * a / rings; pts.append([self.w(cx + rx * math.sin(t) * math.cos(2 * math.pi * k / segs), cy + rx * math.sin(t) * math.sin(2 * math.pi * k / segs), cz + rz * math.cos(t)) for k in range(segs)])
        for a in range(rings):
            for k in range(segs): quad(key, pts[a][k], pts[a][(k + 1) % segs], pts[a + 1][(k + 1) % segs], pts[a + 1][k])

APRON = 4.5
def plot(i, d, key, extra=None, mass_h=None):
    W, D, H = d["widthM"], d["depthM"], d["heightM"]; H = mass_h or H
    i.box("apron", 0, -D / 2 + APRON / 2, 0, W, APRON, 0.12)                               # front apron: drain slab / walkway / pole line (open, in front of the wall)
    i.box(key, 0, APRON / 2, 0, W, D - APRON, H)                                           # the envelope: the most volume the plot may occupy
    if extra: extra(i, W, D, d["heightM"])

def pole(i, d, key="poles_lights_signs", arms=0):
    h = d["heightM"]; i.prism(key, 0, 0, 0, 0.32, h, 6)
    if arms == 1: i.box(key, 0, -d["widthM"] / 2 + 0.2, h - 0.5, 0.15, d["widthM"], 0.15)           # arm towards the road (front)
    if arms == 2: i.box(key, 0, 0, h - 0.5, d["widthM"], 0.15, 0.15)                                 # median: arms across the carriageways
    if arms == 3: i.box(key, 0, 0, h - 0.8, d["widthM"], 0.12, 0.12)                                 # crossarm

def build_instance(p):
    d = INV[p["prop"]]; i = Inst(p["x"], p["y"], p["z"], p["yaw"], p["scale"]); pid = p["prop"]; W, D, H = d["widthM"], d["depthM"], d["heightM"]
    if pid.startswith("kano_hausa_compound"): plot(i, d, "plot_traditional")
    elif pid.startswith("kano_compound_modern"): plot(i, d, "plot_modern")
    elif pid.startswith("kano_shop_row"): plot(i, d, "plot_commercial")
    elif pid in ("kano_plaza_a", "kano_apartment_block_a", "kano_midrise_a"): plot(i, d, "tall_modern")
    elif pid == "kano_mosque_neighbourhood_a":
        plot(i, d, "religious", lambda i, W, D, H: i.box("religious", -W / 2 + 2.0, -D / 2 + APRON + 2.0, 0, 3.0, 3.0, H), mass_h=9.0)   # a main mass (placeholder 9 m) and a tall thin tower marking the planned 24 m height
    elif pid == "kano_filling_station_a":
        i.box("apron", 0, 0, 0, W, D, 0.12); i.box("fuel", 0, D / 2 - 4.5, 0, 14.0, 7.0, 4.0)
        for sx in (-1, 1):
            for sy in (-1, 1): i.prism("fuel", sx * 8.0, -3.0 + sy * 4.0, 0, 0.5, H - 0.6, 6)
        i.box("fuel", 0, -3.0, H - 0.6, 20.0, 12.0, 0.6)
    elif pid == "kano_road_sign_small": i.prism("poles_lights_signs", 0, 0, 0, 0.12, H, 6); i.box("poles_lights_signs", 0, -0.1, H - 1.3, W, 0.08, 0.9)
    elif pid == "kano_road_sign_gantry":
        for sx in (-1, 1): i.prism("poles_lights_signs", sx * (W / 2 - 0.4), 0, 0, 0.5, H, 6)
        i.box("poles_lights_signs", 0, 0, H - 1.8, W, 0.4, 1.8)
    elif pid == "kano_billboard_a":
        for sx in (-1, 1): i.prism("poles_lights_signs", sx * W * 0.3, 0, 0, 0.4, H - 3.0, 6)
        i.box("billboard", 0, 0, H - 4.0, W, 0.5, 4.0)
    elif pid == "kano_streetlight_single": pole(i, d, arms=1)
    elif pid == "kano_streetlight_double_median": pole(i, d, arms=2)
    elif pid == "kano_utility_pole": pole(i, d, arms=3)
    elif pid == "kano_transformer_pole": pole(i, d, arms=3); i.box("poles_lights_signs", 0, 0, H - 3.2, 1.0, 0.9, 1.1)
    elif pid in ("kano_kiosk_a", "kano_market_stall_a"): i.box("street_props", 0, 0, 0, W, D, H)
    elif pid == "kano_bus_stop_a":
        for sx in (-1, 1): i.prism("street_props", sx * (W / 2 - 0.3), D / 2 - 0.3, 0, 0.2, H, 6)
        i.box("street_props", 0, 0, H - 0.2, W, D, 0.2)
    elif pid == "kano_parked_minibus_a": i.box("vehicles", 0, 0, 0.25, W, D, H - 0.25)
    elif pid == "kano_parked_group_a":
        i.box("vehicles", -W / 2 + 0.9 + 0.0, 0, 0.2, 1.8, 4.2, 1.25); i.box("vehicles", 0.9, -1.0, 0.2, 0.8, 2.0, 1.1); i.box("vehicles", 2.2, 0.8, 0.2, 0.8, 2.0, 1.1)
    elif pid == "kano_parked_group_b":
        i.box("vehicles", -2.0, 0, 0.2, 1.3, 2.7, 1.6); i.box("vehicles", -0.3, 0.3, 0.2, 1.3, 2.7, 1.6); i.box("vehicles", 1.7, -0.6, 0.2, 0.8, 2.0, 1.1)
    elif pid.startswith("kano_neem_tree"): i.prism("tree", 0, 0, 0, 0.45, H * 0.5, 6); i.ball("tree", 0, 0, H * 0.62, W / 2, H * 0.38)
    elif pid == "kano_date_palm_a": i.prism("tree", 0, 0, 0, 0.5, H - 1.5, 6); i.ball("tree", 0, 0, H - 1.2, W / 2, 1.2)
    elif pid == "kano_shrub_a": i.ball("ground_cover", 0, 0, H * 0.45, W / 2, H * 0.5, 3, 6)
    else: raise ValueError("no greybox volume for " + pid)

# ---------------------------------------------------------------- ground (the game's own heights, 20 m grid)
T = G["terrain"]; nx, nz, st = T["nx"], T["nz"], T["step"]
for iz in range(nz - 1):
    for ix in range(nx - 1):
        def P(a, b): return (T["x0"] + a * st, T["z0"] + b * st, T["heights"][b * nx + a] - GROUND_DROP)
        quad("ground", P(ix, iz), P(ix + 1, iz), P(ix + 1, iz + 1), P(ix, iz + 1))

# ---------------------------------------------------------------- roads: the game's cross-sections extruded along its centre lines
STRIPS = {0: None, 1: "shoulder", 2: "verge", 3: "median"}
road_quads = 0
for cor in G["corridors"]:
    S_ = cor["samples"]       # [s, x, y, z, fx, fz, scale, run]
    for ri, run in enumerate(cor["runs"]):
        sub = [r for r in S_ if r[7] == ri]
        if not sub: continue
        def lerp_at(s):       # interpolate pos/fwd/scale at an arbitrary s from the 5 m samples
            for a, b in zip(S_, S_[1:]):
                if a[0] <= s <= b[0]:
                    t = 0 if b[0] == a[0] else (s - a[0]) / (b[0] - a[0]); return [s] + [a[k] + (b[k] - a[k]) * t for k in range(1, 7)]
            return [s] + S_[-1][1:7]
        ring = [lerp_at(run["s0"])] + [r[:7] for r in sub if run["s0"] < r[0] < run["s1"]] + [lerp_at(run["s1"])]
        asphalt = "asphalt_" + run["surface"].lower(); pts = run["section"]
        prev = None
        for r in ring:
            s, x, y, z, fx, fz, k = r; rx, rz = fz, -fx
            row = [(x + rx * p[0] * k, z + rz * p[0] * k, y + p[1]) for p in pts]
            if prev is not None:
                for j in range(len(pts) - 1):
                    strip = pts[j][2]; key = asphalt if strip == 0 else STRIPS[strip]
                    quad(key, prev[j], prev[j + 1], row[j + 1], row[j]); road_quads += 1
            prev = row

# ---------------------------------------------------------------- instances
counts = {}
for p in G["instances"]:
    build_instance(p); counts[p["prop"]] = counts.get(p["prop"], 0) + 1

# ---------------------------------------------------------------- objects, one per material key, under one empty
root = bpy.data.objects.new("kano_slice_greybox", None); bpy.context.scene.collection.objects.link(root)
nverts = nfaces = 0
for key, (v, f) in B.items():
    me = bpy.data.meshes.new("GB_" + key); me.from_pydata([tuple(q) for q in v], [], f); me.update()
    me.materials.append(mat(key)); o = bpy.data.objects.new("GB_" + key, me); bpy.context.scene.collection.objects.link(o); o.parent = root
    nverts += len(v); nfaces += len(f)
result = {"objects": len(B), "instances": sum(counts.values()), "byProp": counts, "roadQuads": road_quads, "verts": nverts, "faces": nfaces, "routeLengthM": G["routeLengthM"],
          "legend": {k: [round(c, 2) for c in COLOURS[k]] for k in COLOURS}, "note": "greybox: placeholder volumes, category colours, no style claim"}
